#!/usr/bin/env python3
"""
Post-Migration SHA Verification Tool

Compares SHA-256 checksums of packages between GitLab source and GitHub destination
to detect integrity changes that may occur during cross-platform migration.

Background:
    During GH-to-GH package migrations, SHAs were observed to change after migration.
    This tool verifies whether the same issue occurs in GitLab-to-GitHub migrations.

Usage:
    # Compare using a migration report (generated by migrate_packages.py)
    python verify_sha.py --report migration_report.json \
        --gitlab-token glpat-xxx --github-token ghp_xxx --github-org my-org

    # Full scan: compare all packages in GitLab group vs GitHub org
    python verify_sha.py --full-scan --gitlab-group my-org --gitlab-token glpat-xxx \
        --github-token ghp_xxx --github-org my-org

    # Verify a specific package
    python verify_sha.py --package-name my-package --package-version 1.0.0 \
        --gitlab-project-id 123 --gitlab-token glpat-xxx \
        --github-token ghp_xxx --github-org my-org --github-repo my-repo

Environment variables:
    GITLAB_URL    - GitLab instance URL (default: https://gitlab.com)
    GITLAB_TOKEN  - GitLab PAT
    GITHUB_TOKEN  - GitHub PAT
    GITHUB_ORG    - GitHub organization
"""

import argparse
import hashlib
import json
import logging
import os
import sys
import tempfile
import time
from datetime import datetime
from pathlib import Path
from urllib.parse import quote

import requests

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------

VERSION = "1.0.0"
DEFAULT_GITLAB_URL = "https://gitlab.com"
DEFAULT_GITHUB_API = "https://api.github.com"

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------

_logger = logging.getLogger("sha_verification")


def setup_logging(debug=False, log_file=None):
    level = logging.DEBUG if debug else logging.INFO
    _logger.setLevel(level)
    fmt = logging.Formatter("[%(asctime)s] %(levelname)s - %(message)s", datefmt="%Y-%m-%d %H:%M:%S")

    console = logging.StreamHandler(sys.stdout)
    console.setLevel(level)
    console.setFormatter(fmt)
    _logger.addHandler(console)

    if log_file:
        fh = logging.FileHandler(log_file, mode="w", encoding="utf-8")
        fh.setLevel(logging.DEBUG)
        fh.setFormatter(fmt)
        _logger.addHandler(fh)


def log(msg):
    _logger.info(msg)


def debug_log(msg):
    _logger.debug(msg)


def error_log(msg):
    _logger.error(msg)


